"""Dismissal of a dialog that persists across two checks. Pure module."""

from __future__ import annotations

import math


def _measured(value):
    try:
        fx, fy = value
    except (TypeError, ValueError):
        return None
    if not all(isinstance(v, (int, float)) and math.isfinite(v) and 0.0 <= v <= 1.0 for v in (fx, fy)):
        return None
    return (float(fx), float(fy))


def verdict(previous, current):
    """Where to click to dismiss the dialog, or None. Never raises."""
    try:
        if _measured(previous) is None or _measured(current) is None:
            return None
        return _measured(current)
    except Exception:
        return None

import time


def poll(client):
    while client.alive():
        frame = client.capture()
        client.publish(frame)
        time.sleep(1)

